// Utility: shuffle
function shuffle(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
  return array;
}

// --- Test Et Feature ---
let quizWords = shuffle(words.slice());
let quizIndex = 0;

function loadQuizQuestion() {
  const curr = quizWords[quizIndex];
  document.getElementById('question').innerText = curr.en;

  // Prepare options: correct + 3 random wrongs
  let wrongs = words.filter(w => w.tr !== curr.tr);
  shuffle(wrongs);
  let options = [curr.tr, wrongs[0].tr, wrongs[1].tr, wrongs[2].tr];
  shuffle(options);

  const optionsDiv = document.getElementById('options');
  optionsDiv.innerHTML = '';
  options.forEach(opt => {
    const btn = document.createElement('button');
    btn.className = 'option';
    btn.innerText = opt;
    btn.onclick = () => {
      if (btn.disabled) return;
      if (opt === curr.tr) {
        btn.style.backgroundColor = 'lightgreen';
      } else {
        btn.style.backgroundColor = 'lightcoral';
        // Highlight correct answer
        Array.from(optionsDiv.children).forEach(b => {
          if (b.innerText === curr.tr) b.style.backgroundColor = 'lightgreen';
        });
      }
      // Disable all options
      Array.from(optionsDiv.children).forEach(b => b.disabled = true);
      document.getElementById('nextBtn').disabled = false;
    };
    optionsDiv.appendChild(btn);
  });

  const nextBtn = document.getElementById('nextBtn');
  nextBtn.disabled = true;
  nextBtn.onclick = () => {
    if (quizIndex < quizWords.length - 1) {
      quizIndex++;
      loadQuizQuestion();
    } else {
      alert('Test tamamlandı!');
    }
  };
}

// --- Sürükle Bırak Feature ---
function initDragDrop() {
  const pairs = shuffle(words.slice()).slice(0, 5).map((w, i) => ({ id: i, en: w.en, tr: w.tr }));
  const trList = document.getElementById('trList');
  const enList = document.getElementById('enList');
  trList.innerHTML = '';
  enList.innerHTML = '';

  pairs.forEach(p => {
    const dz = document.createElement('div');
    dz.className = 'drop-zone';
    dz.innerText = p.tr;
    dz.dataset.id = p.id;
    dz.addEventListener('dragover', e => e.preventDefault());
    dz.addEventListener('drop', e => {
      e.preventDefault();
      const draggedId = e.dataTransfer.getData('text');
      const draggedEl = document.querySelector(`.item[data-id='${draggedId}']`);
      if (draggedId === dz.dataset.id) {
        dz.style.backgroundColor = 'lightgreen';
        dz.innerText = p.tr + ' - ' + p.en;
        draggedEl.remove();
      }
    });
    trList.appendChild(dz);
  });

  shuffle(pairs).forEach(p => {
    const it = document.createElement('div');
    it.className = 'item';
    it.innerText = p.en;
    it.draggable = true;
    it.dataset.id = p.id;
    it.addEventListener('dragstart', e => {
      e.dataTransfer.setData('text', p.id);
    });
    enList.appendChild(it);
  });
}

// --- Tab Switching ---
document.getElementById('testTab').onclick = () => {
  document.getElementById('testTab').classList.add('active');
  document.getElementById('dragTab').classList.remove('active');
  document.getElementById('testContainer').classList.add('active');
  document.getElementById('dragContainer').classList.remove('active');
};
document.getElementById('dragTab').onclick = () => {
  document.getElementById('dragTab').classList.add('active');
  document.getElementById('testTab').classList.remove('active');
  document.getElementById('dragContainer').classList.add('active');
  document.getElementById('testContainer').classList.remove('active');
};

window.onload = () => {
  loadQuizQuestion();
  initDragDrop();
};
